const CACHE='antichess-trainer-v4';const ASSETS=['./','./index.html','./style.css','./app.js','./rules.js','./importer.js','./manifest.webmanifest','./icon-192.png','./icon-512.png',...['w','b'].flatMap(color=>['K','Q','R','B','N','P'].map(role=>`./assets/cburnett/${color}${role}.svg`))];self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS)).then(()=>self.skipWaiting())));self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));self.addEventListener('fetch',e=>{if(e.request.method==='GET'&&new URL(e.request.url).origin===location.origin)e.respondWith(caches.match(e.request).then(c=>c||fetch(e.request)))})
